public function payment_fields(): void
{
    PayseraHTMLHelper::enqueueCSS('paysera-payment-css', PayseraPaths::PAYSERA_PAYMENT_CSS);
    PayseraHTMLHelper::enqueueJS(
        'paysera-payment-frontend-js',
